// Transforma o array de issues em itens individuais do n8n, um por issue,
// pra que o proximo node (GET individual) rode uma vez por issue.
// Se nao houver nenhuma issue elegivel, sinaliza isso explicitamente
// (em vez de simplesmente nao produzir nada), pra permitir liberar a
// trava global mesmo quando nao ha nada pra processar nesta rodada.

const response = $input.first().json;
const issues = response.issues || [];

if (issues.length === 0) {
  return [{ json: { no_eligible_tickets: true } }];
}

return issues.map((issue) => ({ json: { id: issue.id } }));

// Prepara o payload de geracao/atualizacao de artefatos a partir da issue
// individual (ja veio com journals). Roda uma vez por issue.

const AUTOMATION_NOTE_PREFIX = "Resultado automatizado do Workflow";

const issue = $input.first().json.issue;
if (!issue) return [];

// Aceita issues em "New" (1) OU "Questions Answered" (14) -- esta segunda
// so e definida pelo proprio app quando o administrador confirma que
// respondeu todas as perguntas em aberto (nao e tempo real: o app decide
// quando o Workflow 1 deve reprocessar, nao o Workflow 1 sozinho).

const ELIGIBLE_STATUS_IDS = [1, 14];
if (!ELIGIBLE_STATUS_IDS.includes(issue.status.id)) return [];

const aiProcessingRequired = (issue.custom_fields || [])
  .find((f) => f.name === "AI Processing Required");
if (!aiProcessingRequired || aiProcessingRequired.value !== "1") return [];

// Le o snapshot da ultima analise (campo customizado "Latest Artifacts
// Snapshot", id 5) -- vem vazio na primeira rodada.
const snapshotField = (issue.custom_fields || []).find((f) => f.id === 5);
const previousSnapshot = snapshotField && snapshotField.value ? snapshotField.value : null;

// So manda os comentarios humanos ADICIONADOS DEPOIS da ultima nota da
// automacao -- isso mantem o prompt do tamanho de "uma rodada", nunca do
// historico inteiro do chamado (era a causa do erro ENAMETOOLONG).
const journals = issue.journals || [];
let lastAutomationIndex = -1;
journals.forEach((j, idx) => {
  if (j.notes && j.notes.trim().startsWith(AUTOMATION_NOTE_PREFIX)) {
    lastAutomationIndex = idx;
  }
});

const relevantJournals = lastAutomationIndex >= 0
  ? journals.slice(lastAutomationIndex + 1)
  : journals;

const latestCommentsText = relevantJournals
  .filter((j) => j.notes && j.notes.trim().length > 0 && !j.notes.trim().startsWith(AUTOMATION_NOTE_PREFIX))
  .map((j) => {
    const author = (j.user && j.user.name) || "desconhecido";
    const date = j.created_on || "";
    return `[${date}] ${author}: ${j.notes.trim()}`;
  })
  .join("\n\n");

return [
  {
    json: {
      issue_id: issue.id,
      title: issue.subject,
      description: issue.description || "",
      previous_snapshot: previousSnapshot,
      latest_comments_text: latestCommentsText,
    },
  },
];

// Interpreta a resposta do endpoint /redmine/generate-artifacts, monta a
// nota + status final da issue, e prepara os campos customizados a
// atualizar:
//   id 5 -- snapshot consolidado (JSON)
//   id 6 -- contador de tentativas de desenvolvimento (reset para 0)
//   id 7 -- perguntas em aberto, SO em PT-BR, sobrescrito a cada rodada
//           (vazio quando nao ha nenhuma pendente). E este campo que o
//           app/Lovable deve ler para mostrar ao administrador -- nao a
//           nota completa, que mistura analise tecnica em ingles.

const STATUS_WAITING_FOR_ARTIFACT_APPROVAL = 4;
const STATUS_WAITING_FOR_ANSWERS = 13;
const STATUS_AUTOMATION_ERROR = 11;

const item = $input.first().json;
const issueId = item.issue_id;
const worker = item;

const failed = worker.error || typeof worker.summary === "undefined";

const summary = worker.summary || "(sem summary retornado pelo worker)";
const classification = worker.issue_classification || "";
const userStory = worker.user_story || "";
const acceptanceCriteria = Array.isArray(worker.acceptance_criteria) ? worker.acceptance_criteria : [];
const modulesAffected = Array.isArray(worker.system_modules_affected) ? worker.system_modules_affected : [];
const devTasks = Array.isArray(worker.development_tasks) ? worker.development_tasks : [];
const testCases = Array.isArray(worker.test_cases) ? worker.test_cases : [];
const openQuestions = Array.isArray(worker.open_questions) ? worker.open_questions : [];
const warnings = Array.isArray(worker.warnings) ? worker.warnings : [];

const notesLines = [
  `Resultado automatizado do Workflow 1 (Geração de Artefatos via Claude Code):`,
  ``,
];

if (!failed && openQuestions.length > 0) {
  notesLines.push(
    `Este chamado tem perguntas em aberto -- aguardando respostas do administrador antes de prosseguir para aprovação.`,
    ``
  );
}

notesLines.push(`Resumo: ${summary}`);

if (classification) notesLines.push(``, `Classificação: ${classification}`);
if (userStory) notesLines.push(``, `User Story: ${userStory}`);
if (acceptanceCriteria.length) notesLines.push(``, `Critérios de aceite:`, ...acceptanceCriteria.map((c) => `- ${c}`));
if (modulesAffected.length) notesLines.push(``, `Módulos afetados: ${modulesAffected.join(", ")}`);
if (devTasks.length) notesLines.push(``, `Tarefas de desenvolvimento:`, ...devTasks.map((t) => `- ${t}`));
if (testCases.length) notesLines.push(``, `Casos de teste:`, ...testCases.map((t) => `- ${t}`));
if (openQuestions.length) notesLines.push(``, `Perguntas em aberto:`, ...openQuestions.map((q) => `- ${q}`));
if (warnings.length) notesLines.push(``, `Avisos:`, ...warnings.map((w) => `- ${w}`));
if (worker.error) notesLines.push(``, `Erro do worker: ${worker.error}`);

let statusId;
if (failed) {
  statusId = STATUS_AUTOMATION_ERROR;
} else if (openQuestions.length > 0) {
  statusId = STATUS_WAITING_FOR_ANSWERS;
} else {
  statusId = STATUS_WAITING_FOR_ARTIFACT_APPROVAL;
}

let customFields = [];
if (!failed) {
  const snapshot = {
    summary,
    issue_classification: classification,
    user_story: userStory,
    acceptance_criteria: acceptanceCriteria,
    system_modules_affected: modulesAffected,
    development_tasks: devTasks,
    test_cases: testCases,
    open_questions: openQuestions,
  };
  customFields.push({ id: 5, value: JSON.stringify(snapshot) });
  customFields.push({ id: 6, value: "0" });

  // Campo 7: SO as perguntas, em PT-BR, sobrescrito a cada rodada.
  // Vazio quando nao ha nenhuma pendente (limpa automaticamente quando
  // a issue sai de "tem perguntas" para "pronta pra aprovacao").
  const openQuestionsText = openQuestions.length
    ? openQuestions.map((q) => `- ${q}`).join("\n")
    : "";
  customFields.push({ id: 7, value: openQuestionsText });
}

return [
  {
    json: {
      issue_id: issueId,
      status_id: statusId,
      notes: notesLines.join("\n"),
      custom_fields: customFields,
    },
  },
];

// Verifica a trava GLOBAL (Data Table "automation_lock", linha lock_name="global").
// Diferente da trava por chamado (campo "Automation Status" no Redmine, que
// impede a MESMA issue ser pega duas vezes) -- esta impede que QUALQUER
// combinacao dos workflows 1/2/3 rode ao mesmo tempo, ja que todos
// compartilham o mesmo worker/sessao do Claude Code conectada ao Lovable.

const LOCK_TIMEOUT_MINUTES = 30; // bem maior que qualquer timeout de worker configurado

const row = $input.first().json;
const status = row.status || "idle";
const lockedAt = row.locked_at || "";

if (status === "running" && lockedAt) {
  const lockAgeMinutes = (Date.now() - new Date(lockedAt).getTime()) / 60000;
  if (!isNaN(lockAgeMinutes) && lockAgeMinutes < LOCK_TIMEOUT_MINUTES) {
    return []; // outro workflow esta rodando agora -- para aqui, nada foi adquirido
  }
  // trava velha demais (execucao anterior travou/crashou sem liberar) -- segue e assume
}

return [{ json: { proceed: true } }];
